"""Keep upgrade instructions in the notes generated by the publishing workflow."""

import os
import subprocess
import textwrap
from pathlib import Path


def test_published_release_notes_include_upgrade_notes(tmp_path):
    workflow = (Path(__file__).parents[1] / ".github/workflows/release.yml").read_text()
    step = workflow.split("      - name: Prepare release notes\n", 1)[1].split(
        "      - name: Create GitHub Release\n", 1
    )[0]
    script = textwrap.dedent(step.split("        run: |\n", 1)[1])
    (tmp_path / "CHANGELOG.md").write_text(
        "## [1.3.0] - 2026-11-02\n\n"
        "### Upgrade notes\n\nBack up the database before upgrading.\n\n"
        "### Added\n\nCatch up imported likes.\n\n"
        "### Changed\n\nPreserve playback positions.\n\n"
        "### Fixed\n\nKeep saved media.\n\n"
        "### Internal\n\nDo not publish this section.\n\n"
        "## [1.2.0] - 2026-10-25\n\n"
        "### Fixed\n\nDo not repeat the previous release.\n"
    )
    subprocess.run(
        ["bash", "-eu", "-c", script],
        cwd=tmp_path,
        env={
            **os.environ,
            "TAG": "v1.3.0",
            "REPOSITORY": "example/tweetnook",
            "RUNNER_TEMP": str(tmp_path),
        },
        check=True,
        capture_output=True,
        text=True,
    )

    assert (tmp_path / "release-notes.md").read_text().strip() == (
        "### Upgrade notes\n\nBack up the database before upgrading.\n\n"
        "### Added\n\nCatch up imported likes.\n\n"
        "### Changed\n\nPreserve playback positions.\n\n"
        "### Fixed\n\nKeep saved media."
    )
